import sys

def main():
    data = sys.stdin.read().split()
    s = data[0]
    k = int(data[1])
    st = []
    for ch in s:
        if st and st[-1][0] == ch:
            st[-1][1] += 1
            if st[-1][1] == k:
                st.pop()
        else:
            st.append([ch, 1])
    print(''.join(c * m for c, m in st))

